#include <algorithm>
#include <cstdint>
#include <string>
#include <vector>

std::int64_t relativeDue(std::int64_t milliseconds)
{
    if (milliseconds <= 0) return -1;
    return -milliseconds * 10'000;
}

std::int64_t msUntilFire(std::int64_t due, std::int64_t now)
{
    if (due < 0) return -due / 10'000;
    return due > now ? (due - now) / 10'000 : 0;
}

int firesBetween(std::int64_t first, int period, std::int64_t from, std::int64_t to)
{
    if (to <= from) return 0;
    if (period <= 0) return first > from && first <= to ? 1 : 0;
    auto upTo = [&](std::int64_t t) -> std::int64_t { return t < first ? 0 : (t - first) / period + 1; };   // fires at or before t
    return static_cast<int>(upTo(to) - upTo(from));
}

std::string checkUnload(const std::vector<std::string>& steps)
{
    const std::vector<std::string> all{ "cancel timer", "flush dpcs", "wait work items", "free context", "delete link", "delete device" };
    for (const std::string& s : all)
    {
        const auto n{ std::count(steps.begin(), steps.end(), s) };
        if (n == 0) return "missing " + s;
        if (n > 1) return "twice " + s;
    }
    auto pos = [&](const std::string& s) { return std::find(steps.begin(), steps.end(), s) - steps.begin(); };
    if (pos("flush dpcs") < pos("cancel timer")) return "flush dpcs before cancel timer";
    if (pos("free context") < pos("flush dpcs")) return "free context before flush dpcs";
    if (pos("free context") < pos("wait work items")) return "free context before wait work items";
    if (pos("delete device") < pos("delete link")) return "delete device before delete link";
    return "";
}

unitTests:
TEST("due times") {
    CHECK_EQ(relativeDue(1000), std::int64_t{ -10'000'000 }); CHECK_EQ(relativeDue(1), std::int64_t{ -10'000 }); CHECK_EQ(relativeDue(0), std::int64_t{ -1 });
    CHECK_EQ(msUntilFire(-25'000'000, 0), std::int64_t{ 2500 }); CHECK_EQ(msUntilFire(-1, 0), std::int64_t{ 0 });
    const std::int64_t now = 133'000'000'000'000'000LL; CHECK_EQ(msUntilFire(now + 50'000'000, now), std::int64_t{ 5000 }); CHECK_EQ(msUntilFire(100'000'000, now), std::int64_t{ 0 });
}
TEST("periodic fires") {
    CHECK_EQ(firesBetween(1000, 250, 0, 1000), 1); CHECK_EQ(firesBetween(1000, 250, 0, 2000), 5); CHECK_EQ(firesBetween(1000, 250, 1000, 1499), 1); CHECK_EQ(firesBetween(1000, 250, 1001, 1249), 0);
    CHECK_EQ(firesBetween(1000, 0, 0, 5000), 1); CHECK_EQ(firesBetween(1000, 0, 1000, 5000), 0); CHECK_EQ(firesBetween(1000, 250, 500, 400), 0);
}
TEST("unload order") {
    CHECK_EQ(checkUnload({ "cancel timer", "flush dpcs", "wait work items", "free context", "delete link", "delete device" }), std::string(""));
    CHECK_EQ(checkUnload({ "delete link", "cancel timer", "wait work items", "flush dpcs", "delete device", "free context" }), std::string(""));
    CHECK_EQ(checkUnload({ "flush dpcs", "cancel timer", "wait work items", "free context", "delete link", "delete device" }), std::string("flush dpcs before cancel timer"));
    CHECK_EQ(checkUnload({ "cancel timer", "free context", "flush dpcs", "wait work items", "delete link", "delete device" }), std::string("free context before flush dpcs"));
    CHECK_EQ(checkUnload({ "cancel timer", "flush dpcs", "free context", "wait work items", "delete link", "delete device" }), std::string("free context before wait work items"));
    CHECK_EQ(checkUnload({ "cancel timer", "flush dpcs", "wait work items", "free context", "delete device", "delete link" }), std::string("delete device before delete link"));
    CHECK_EQ(checkUnload({ "flush dpcs", "wait work items", "free context", "delete link", "delete device" }), std::string("missing cancel timer"));
    CHECK_EQ(checkUnload({ "cancel timer", "cancel timer", "flush dpcs", "wait work items", "free context", "delete link", "delete device" }), std::string("twice cancel timer"));
}

